using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using RedKey.Domain.Entities.Units;

namespace RedKey.Persistence.Configurations.Units;

internal sealed class PropertyUnitConfiguration : IEntityTypeConfiguration<PropertyUnit>
{
    public void Configure(EntityTypeBuilder<PropertyUnit> builder)
    {
        builder.ToTable(TableNames.Units);
        builder.HasKey(u => u.Id);
        builder.Property(u => u.Id).ValueGeneratedNever();

        // RK-1000, RK-1001... generated by SQL Server on insert.
        builder.Property(u => u.Code)
            .HasMaxLength(20)
            .HasDefaultValueSql($"CONCAT('RK-', NEXT VALUE FOR {TableNames.UnitCodeSequence})")
            .ValueGeneratedOnAdd();
        builder.HasIndex(u => u.Code).IsUnique();

        builder.Property(u => u.TitleAr).HasMaxLength(200).IsRequired();
        builder.Property(u => u.TitleEn).HasMaxLength(200).IsRequired();
        builder.Property(u => u.CompoundAr).HasMaxLength(150).IsRequired();
        builder.Property(u => u.CompoundEn).HasMaxLength(150).IsRequired();
        builder.Property(u => u.CoverImageUrl).HasMaxLength(500).IsRequired();
        builder.Property(u => u.ReviewNote).HasMaxLength(1000);
        builder.Property(u => u.Price).HasPrecision(18, 2);
        builder.Property(u => u.Size).HasPrecision(10, 2);
        builder.Property(u => u.BrokerCommission).HasPrecision(5, 2);
        builder.Property(u => u.ViewingFee).HasPrecision(18, 2);

        // Website listing filters + broker "my units".
        builder.HasIndex(u => new { u.Status, u.Purpose, u.UnitTypeId, u.CityId, u.AreaId });
        builder.HasIndex(u => u.CreatedByUserId);

        builder.HasQueryFilter(u => !u.IsDeleted);

        builder.HasOne(u => u.UnitType).WithMany().HasForeignKey(u => u.UnitTypeId).OnDelete(DeleteBehavior.Restrict);
        builder.HasOne(u => u.City).WithMany().HasForeignKey(u => u.CityId).OnDelete(DeleteBehavior.Restrict);
        builder.HasOne(u => u.Area).WithMany().HasForeignKey(u => u.AreaId).OnDelete(DeleteBehavior.Restrict);
        builder.HasOne(u => u.CreatedBy).WithMany().HasForeignKey(u => u.CreatedByUserId).OnDelete(DeleteBehavior.Restrict);

        builder.HasOne(u => u.Details).WithOne().HasForeignKey<UnitDetails>(d => d.UnitId).OnDelete(DeleteBehavior.Cascade);

        builder.HasMany(u => u.Images).WithOne().HasForeignKey(i => i.UnitId).OnDelete(DeleteBehavior.Cascade);
        builder.HasMany(u => u.PaymentPlans).WithOne().HasForeignKey(p => p.UnitId).OnDelete(DeleteBehavior.Cascade);
        builder.HasMany(u => u.Features).WithOne().HasForeignKey(f => f.UnitId).OnDelete(DeleteBehavior.Cascade);

        builder.Navigation(u => u.Images).UsePropertyAccessMode(PropertyAccessMode.Field);
        builder.Navigation(u => u.PaymentPlans).UsePropertyAccessMode(PropertyAccessMode.Field);
        builder.Navigation(u => u.Features).UsePropertyAccessMode(PropertyAccessMode.Field);
    }
}

internal sealed class UnitDetailsConfiguration : IEntityTypeConfiguration<UnitDetails>
{
    public void Configure(EntityTypeBuilder<UnitDetails> builder)
    {
        builder.ToTable(TableNames.UnitDetails);
        builder.HasKey(d => d.UnitId);

        builder.Property(d => d.DescriptionAr).HasMaxLength(4000).IsRequired();
        builder.Property(d => d.DescriptionEn).HasMaxLength(4000).IsRequired();
        builder.Property(d => d.DeliveryAr).HasMaxLength(100);
        builder.Property(d => d.DeliveryEn).HasMaxLength(100);
    }
}

internal sealed class UnitImageConfiguration : IEntityTypeConfiguration<UnitImage>
{
    public void Configure(EntityTypeBuilder<UnitImage> builder)
    {
        builder.ToTable(TableNames.UnitImages);
        builder.HasKey(i => i.Id);
        builder.Property(i => i.Url).HasMaxLength(500).IsRequired();
        builder.HasIndex(i => new { i.UnitId, i.SortOrder });
    }
}

internal sealed class UnitPaymentPlanConfiguration : IEntityTypeConfiguration<UnitPaymentPlan>
{
    public void Configure(EntityTypeBuilder<UnitPaymentPlan> builder)
    {
        builder.ToTable(TableNames.UnitPaymentPlans);
        builder.HasKey(p => p.Id);
        builder.Property(p => p.LabelAr).HasMaxLength(150).IsRequired();
        builder.Property(p => p.LabelEn).HasMaxLength(150).IsRequired();
        builder.Property(p => p.ValueAr).HasMaxLength(150).IsRequired();
        builder.Property(p => p.ValueEn).HasMaxLength(150).IsRequired();
        builder.HasIndex(p => new { p.UnitId, p.SortOrder });
    }
}

internal sealed class UnitFeatureConfiguration : IEntityTypeConfiguration<UnitFeature>
{
    public void Configure(EntityTypeBuilder<UnitFeature> builder)
    {
        builder.ToTable(TableNames.UnitFeatures);
        builder.HasKey(f => f.Id);
        builder.Property(f => f.NameAr).HasMaxLength(100).IsRequired();
        builder.Property(f => f.NameEn).HasMaxLength(100).IsRequired();
        builder.HasIndex(f => new { f.UnitId, f.SortOrder });
    }
}
